import{Z as t,e as o,f as i,a0 as n}from"./chunks/framework.DmpHOl9T.js";const p=JSON.parse('{"title":"Procurios","description":"","frontmatter":{},"headers":[],"relativePath":"integrations/crm/procurios.md","filePath":"integrations/crm/procurios.md","lastUpdated":1780377007000}'),r={name:"integrations/crm/procurios.md"};function a(s,e,c,l,h,d){return o(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="procurios" tabindex="-1">Procurios <a class="header-anchor" href="#procurios" aria-label="Permalink to &quot;Procurios&quot;">​</a></h1><p>Connect Procurios to send enquiries to the records your team manages. You need access to configure the form in Craft and credentials for the destination account. The steps below establish the connection; finish by sending a test submission to verify the result.</p><h3 id="step-1-create-the-integration" tabindex="-1">Step 1. Create the Integration <a class="header-anchor" href="#step-1-create-the-integration" aria-label="Permalink to &quot;Step 1. Create the Integration&quot;">​</a></h3><ol><li>Navigate to <strong>Formie</strong> → <strong>Settings</strong> → <strong>CRM</strong>.</li><li>Click the <strong>New Integration</strong> button.</li><li>Select Procurios as the <strong>Integration Provider</strong>.</li></ol><h3 id="step-2-connect-to-the-procurios-api" tabindex="-1">Step 2. Connect to the Procurios API <a class="header-anchor" href="#step-2-connect-to-the-procurios-api" aria-label="Permalink to &quot;Step 2. Connect to the Procurios API&quot;">​</a></h3><ol><li>Go to <a href="https://www.procurios.com/en/" target="_blank">Procurios</a> and login to your account.</li><li>Go to the <strong>Settings</strong> or <strong>Developers</strong> section.</li><li>Locate the area to manage <strong>OAuth Applications</strong>.</li><li>Register a new application.</li><li>In the <strong>Redirect URI</strong> field, enter the value from the <strong>Redirect URI</strong> field in Formie.</li><li>Copy the <strong>Client ID</strong> from Procurios and paste in the <strong>Client ID</strong> field in Formie.</li><li>Copy the <strong>Client Secret</strong> from Procurios and paste in the <strong>Client Secret</strong> field in Formie.</li></ol><h3 id="step-3-test-connection" tabindex="-1">Step 3. Test Connection <a class="header-anchor" href="#step-3-test-connection" aria-label="Permalink to &quot;Step 3. Test Connection&quot;">​</a></h3><ol><li>Save this integration.</li><li>Click on the <strong>Connect</strong> button in the right-hand sidebar.</li><li>You‘ll be redirected to Procurios, where you must approve Formie to access your Procurios account.</li></ol><h3 id="step-4-form-setting" tabindex="-1">Step 4. Form Setting <a class="header-anchor" href="#step-4-form-setting" aria-label="Permalink to &quot;Step 4. Form Setting&quot;">​</a></h3><ol><li>Go to the form you want to enable this integration on.</li><li>Click the <strong>Integrations</strong> tab.</li><li>In the left-hand sidebar, select the name you gave the integration.</li><li>Enable the integration. Choose the record types this integration exposes, then map the required destination fields using the variable picker. For a contact enquiry, map the visitor’s email and name where those fields are available. Use the requirements shown for your selected record type rather than assuming every CRM accepts the same fields.</li><li>Click <strong>Save</strong> to save the form.</li></ol><h2 id="verify-a-submission" tabindex="-1">Verify a Submission <a class="header-anchor" href="#verify-a-submission" aria-label="Permalink to &quot;Verify a Submission&quot;">​</a></h2><p>Save the form, open it on your site and submit recognisable test values. Find the test record in the selected CRM destination. Check the mapped values and whether the integration created a record or updated an existing one as intended.</p><p>If nothing arrives, check whether integration conditions matched, whether the submission was complete and non-spam, and whether Craft’s queue has processed the job. A successful connection check verifies credentials; it does not prove that field mapping and delivery work. See <a href="/integrations/connect-and-test-an-integration">Connect and Test an Integration</a> for a complete mapping and verification workflow.</p>',13)])])}const u=t(r,[["render",a]]);export{p as __pageData,u as default};
